import { handleMemory } from '../doaa-memory.js';
const BUILD='encounter-tracks-11.1';
const RELAY='https://doaa-adsb-relay.onrender.com',RAW='https://raw.githubusercontent.com/brenton-collab/doaa-calibration/main/';
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v)),FRESH=25,STALE=300,TIMEOUT=9000,KEEP=90*60*1000,CLOSE=15*60*1000;
const json=(d,s=200,c='no-store')=>new Response(JSON.stringify(d),{status:s,headers:{'content-type':'application/json; charset=utf-8','cache-control':c,'access-control-allow-origin':'*'}});
async function relay(path,timeout=TIMEOUT){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(RELAY+path,{headers:{Accept:'application/json','User-Agent':'DOAA-Ottawa-Aviation/1.0'},signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw Error(j.error||(j.errors||[]).join(' · ')||`HTTP ${r.status}`);return j}catch(e){throw e}finally{clearTimeout(t)}}
async function acquire(lat,lon,dist){try{const j=await relay(`/traffic?lat=${lat}&lon=${lon}&dist=${dist}`);return{ok:true,build:BUILD,provider:j.provider||'UNKNOWN',relay:j.relay||'UNKNOWN',now:j.now||Date.now(),center:j.center||{lat,lon},dist,aircraft:j.aircraft||[],tracks:j.tracks||{}}}catch(e){return{ok:false,build:BUILD,now:Date.now(),aircraft:[],tracks:{},errors:[e.name==='AbortError'?'RELAY TIMEOUT':e.message]}}}
function merge(a={},b={},now=Date.now()){const out={};for(const src of[a,b])for(const[id0,e]of Object.entries(src||{})){const id=id0.toLowerCase(),cur=out[id]||{firstSeen:e.firstSeen||now,lastSeen:0,points:[]};cur.firstSeen=Math.min(cur.firstSeen,e.firstSeen||now);cur.lastSeen=Math.max(cur.lastSeen,e.lastSeen||0);const pts=[...cur.points,...(e.points||[])].filter(p=>p?.t&&now-p.t<KEEP).sort((x,y)=>x.t-y.t),ded=[];for(const p of pts)if(!ded.length||ded[ded.length-1].t!==p.t)ded.push(p);cur.points=ded;out[id]=cur}for(const[id,e]of Object.entries(out))if(now-(e.lastSeen||0)>CLOSE)delete out[id];return out}
function snaps(list,now){const o={};for(const a of list||[]){const id=String(a.hex||a.icao||'').toLowerCase();if(!id||a.lat==null||a.lon==null||a.alt_baro==='ground')continue;o[id]={firstSeen:now,lastSeen:now,points:[{lat:a.lat,lon:a.lon,t:now,alt:a.alt_baro??a.alt_geom??null,gs:a.gs??null,track:a.track??null}]}}return o}
async function airport(icao){if(!/^[A-Z0-9]{4}$/.test(icao))return json({ok:false,error:'bad airport'},400);const c=new AbortController(),t=setTimeout(()=>c.abort(),6500);try{const r=await fetch(`https://aviationweather.gov/api/data/metar?ids=${icao}&format=json&taf=true`,{headers:{Accept:'application/json','User-Agent':'DOAA-Ottawa-Aviation/1.0'},signal:c.signal});if(!r.ok)throw Error(`METAR ${r.status}`);const j=await r.json();return json({ok:true,icao,metar:Array.isArray(j)?j[0]||null:j},200,'public, max-age=120')}catch(e){return json({ok:false,icao,error:e.name==='AbortError'?'METAR TIMEOUT':e.message},502)}finally{clearTimeout(t)}}
async function airportLookup(q){const code=String(q||'').trim().toUpperCase();if(!/^[A-Z0-9]{3,4}$/.test(code))return json({ok:false,error:'airport code required'},400);
 const oa=async()=>{const urls=[`https://ourairports.com/airports/${encodeURIComponent(code)}/`,`https://ourairports.com/search?q=${encodeURIComponent(code)}`];for(const url of urls)try{const r=await fetch(url,{headers:{Accept:'text/html','User-Agent':'DOAA-Ottawa-Aviation/1.0'},cf:{cacheTtl:86400,cacheEverything:true}});if(!r.ok)continue;const h=await r.text(),m=h.match(/href="\/airports\/([^/"?#]+)\/"[^>]*>([^<]+)<\/a>/i);if(!m)continue;const ident=String(m[1]).toUpperCase();const ar=await fetch('https://aviationweather.gov/api/data/stationinfo?ids='+encodeURIComponent(ident)+'&format=json',{headers:{Accept:'application/json','User-Agent':'DOAA-Ottawa-Aviation/1.0'}});if(!ar.ok)continue;const j=await ar.json(),x=Array.isArray(j)?j[0]:j,lat=Number(x?.lat??x?.latitude),lon=Number(x?.lon??x?.longitude);if(x&&Number.isFinite(lat)&&Number.isFinite(lon))return{icao:String(x.icaoId||x.icao||ident).toUpperCase(),iata:code.length===3?code:null,name:x.site||x.name||x.stationName||m[2]||ident,lat,lon}}catch{}return null};
 if(code.length===4)try{const r=await fetch('https://aviationweather.gov/api/data/stationinfo?ids='+encodeURIComponent(code)+'&format=json',{headers:{Accept:'application/json','User-Agent':'DOAA-Ottawa-Aviation/1.0'}});if(r.ok){const j=await r.json(),x=Array.isArray(j)?j[0]:j,lat=Number(x?.lat??x?.latitude),lon=Number(x?.lon??x?.longitude);if(x&&Number.isFinite(lat)&&Number.isFinite(lon))return json({ok:true,airport:{icao:String(x.icaoId||x.icao||code).toUpperCase(),iata:null,name:x.site||x.name||x.stationName||code,lat,lon},source:'AviationWeather'},200,'public, max-age=86400')}}catch{}
 const hit=await oa();return hit?json({ok:true,airport:hit,source:'OurAirports + AviationWeather'},200,'public, max-age=86400'):json({ok:false,error:'airport not found',query:code},404)}
async function persistRelayKnowledge(env,origin,j){if(!j?.found)return;const f=j.flight||null,a=j.airframe||null,hex=String(f?.hex||a?.hex||'').trim().toUpperCase();if(!hex)return;const ids={icao24:hex};if(f?.reg_number||a?.reg_number)ids.registration=f?.reg_number||a?.reg_number;if(f?.aircraft_icao||a?.icao)ids.icao_type=f?.aircraft_icao||a?.icao;const claims=[],add=(predicate,value)=>{if(value!=null&&value!=='')claims.push({predicate,value,status:'supported'})};add('registration',ids.registration);add('icao_type',ids.icao_type);add('manufacturer',a?.manufacturer||f?.manufacturer);add('model',a?.model||f?.model);add('msn',a?.msn||f?.msn);add('built',a?.built||f?.built);add('engine',a?.engine||f?.engine);add('engine_count',a?.engine_count||f?.engine_count);add('operator',f?.airline_name);if(f?.flight_icao)add('route:'+String(f.flight_icao).toUpperCase(),JSON.stringify({callsign:f.flight_icao,dep_iata:f.dep_iata||null,dep_icao:f.dep_icao||null,arr_iata:f.arr_iata||null,arr_icao:f.arr_icao||null,dep_time:f.dep_time||f.dep_actual||null,arr_time:f.arr_time||f.arr_actual||null}));if(!claims.length)return;await handleMemory(new Request(new URL('/memory/ingest',origin),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({entity:{kind:'airframe',key:hex},identifiers:ids,source:{key:'airlabs-harvest',name:'AirLabs harvested response',kind:'api'},claims})}),env)}
async function saveProviderCursor(env,cursor,epoch){await env.DB.prepare("INSERT INTO provider_state(provider,request_cursor,request_epoch,metered_since,observed_at) VALUES('AIRLABS',?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(provider) DO UPDATE SET request_cursor=excluded.request_cursor,request_epoch=excluded.request_epoch,observed_at=CURRENT_TIMESTAMP").bind(cursor,epoch,new Date().toISOString()).run()}
async function saveHarvestCursor(env,cursor,epoch){await env.DB.prepare("INSERT INTO provider_state(provider,harvest_cursor,harvest_epoch,metered_since,observed_at) VALUES('AIRLABS',?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(provider) DO UPDATE SET harvest_cursor=excluded.harvest_cursor,harvest_epoch=excluded.harvest_epoch,observed_at=CURRENT_TIMESTAMP").bind(cursor,epoch,new Date().toISOString()).run()}
async function drainRelayHarvest(env,origin){let state=await env.DB.prepare("SELECT harvest_cursor,harvest_epoch FROM provider_state WHERE provider='AIRLABS'").first(),cursor=Number(state?.harvest_cursor)||0,epoch=state?.harvest_epoch||null,total=0;for(let page=0;page<3;page++){let j=await relay('/harvest?since='+cursor+'&limit=100',6500);if(j.epoch&&epoch&&j.epoch!==epoch){cursor=0;j=await relay('/harvest?since=0&limit=100',6500)}if(j.epoch)epoch=j.epoch;const items=j.items||[];for(const item of items){await persistRelayKnowledge(env,origin,{found:true,flight:item.flight||null,airframe:item.airframe||null});cursor=Number(item.seq)||cursor;await saveHarvestCursor(env,cursor,epoch);total++}if(!j.has_more)break}return{epoch,cursor,total}}
async function persistProviderEvent(env,x,epoch){const req=x.request||{},h=x.headers||{},num=(...xs)=>{for(const v of xs){const n=Number(v);if(Number.isFinite(n))return n}return null},used=num(req.used,req.requests_used,req.usage,h['x-ratelimit-used'],h['ratelimit-used']),remaining=num(req.remaining,req.requests_remaining,h['x-ratelimit-remaining'],h['ratelimit-remaining']),limit=num(req.limit,req.quota,req.requests_limit,h['x-ratelimit-limit'],h['ratelimit-limit']),reset=String(req.reset_at||req.reset||h['x-ratelimit-reset']||h['ratelimit-reset']||'')||null,authority=(used!=null||remaining!=null||limit!=null||reset!=null)?'provider':'local',fingerprint=epoch+':'+x.seq;
 const inserted=await env.DB.prepare("INSERT OR IGNORE INTO provider_requests(provider,endpoint,occurred_at,units,status,purpose,records_returned,request_fingerprint,metadata_json) VALUES('AIRLABS',?,?,?,?,?,?,?,?)").bind(String(x.path||'unknown'),new Date(Number(x.at)||Date.now()).toISOString(),1,x.ok?'ok':String(x.status||'error'),null,Number(x.records_returned)||0,fingerprint,JSON.stringify({params:x.params||[],request:req,headers:h})).run();
 if((inserted?.meta?.changes||0)>0)await env.DB.prepare("INSERT INTO provider_state(provider,local_calls,metered_since,provider_used,provider_remaining,quota_units,reset_at,authority,observed_at,metadata_json) VALUES('AIRLABS',1,?,?,?,?,?,?,CURRENT_TIMESTAMP,?) ON CONFLICT(provider) DO UPDATE SET local_calls=provider_state.local_calls+1,provider_used=COALESCE(excluded.provider_used,provider_state.provider_used),provider_remaining=COALESCE(excluded.provider_remaining,provider_state.provider_remaining),quota_units=COALESCE(excluded.quota_units,provider_state.quota_units),reset_at=COALESCE(excluded.reset_at,provider_state.reset_at),authority=CASE WHEN excluded.authority='provider' THEN 'provider' ELSE provider_state.authority END,observed_at=CURRENT_TIMESTAMP,metadata_json=excluded.metadata_json").bind(new Date().toISOString(),used,remaining,limit,reset,authority,JSON.stringify({request:req,headers:h})).run()}
async function drainProviderEvents(env){let state=await env.DB.prepare("SELECT request_cursor,request_epoch FROM provider_state WHERE provider='AIRLABS'").first(),cursor=Number(state?.request_cursor)||0,epoch=state?.request_epoch||null,total=0;for(let page=0;page<3;page++){let j=await relay('/provider-events?since='+cursor+'&limit=100',6500);if(j.epoch&&epoch&&j.epoch!==epoch){cursor=0;j=await relay('/provider-events?since=0&limit=100',6500)}if(j.epoch)epoch=j.epoch;for(const x of j.items||[]){await persistProviderEvent(env,x,epoch);cursor=Number(x.seq)||cursor;await saveProviderCursor(env,cursor,epoch);total++}if(!j.has_more)break}return{epoch,cursor,total}}
async function boardApi(u,env){const home=String(u.searchParams.get('home')||'YOW').trim().toUpperCase();try{const j=await relay('/board?home='+encodeURIComponent(home),8000);try{await drainProviderEvents(env);await drainRelayHarvest(env,u.origin)}catch{}return json(j,200,'private, max-age=30')}catch(e){return json({ok:false,error:e.name==='AbortError'?'BOARD TIMEOUT':e.message},502)}}
async function opsApi(env){try{const s=await env.DB.prepare("SELECT provider,harvest_cursor,harvest_epoch,request_cursor,request_epoch,local_calls,metered_since,provider_used,provider_remaining,quota_units,reset_at,authority,observed_at FROM provider_state WHERE provider='AIRLABS'").first();const q=await env.DB.prepare("SELECT COUNT(*) requests,COALESCE(SUM(units),0) units,COALESCE(SUM(records_returned),0) records_returned FROM provider_requests WHERE provider='AIRLABS'").first();return json({ok:true,provider:'AIRLABS',state:s||null,meter:q||{requests:0,units:0,records_returned:0}})}catch(e){return json({ok:false,error:e.message},500)}}

async function flight(u,env){const call=encodeURIComponent(String(u.searchParams.get('call')||'')),hex=encodeURIComponent(String(u.searchParams.get('hex')||''));try{const j=await relay(`/flight?call=${call}&hex=${hex}`,6500);try{await drainProviderEvents(env);await persistRelayKnowledge(env,u.origin,j);await drainRelayHarvest(env,u.origin)}catch{}return json(j,200,'private, max-age=60')}catch(e){return json({ok:false,source:'AIRLABS',error:e.name==='AbortError'?'FLIGHT TIMEOUT':e.message},502)}}

async function adsblolLive(hex){const id=String(hex||'').trim().toLowerCase();if(!/^[0-9a-f]{6}$/.test(id))return null;try{const r=await fetch('https://api.adsb.lol/v2/icao/'+encodeURIComponent(id),{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0','Accept':'application/json'},cf:{cacheTtl:30,cacheEverything:true}});if(!r.ok)return null;const j=await r.json(),a=(j.ac||j.aircraft||[])[0];if(!a)return null;return{source:'ADSB.lol',icao24:id.toUpperCase(),registration:a.r||a.reg||null,type:a.t||a.type||null,callsign:String(a.flight||a.callsign||'').trim().toUpperCase()||null,lat:a.lat??null,lon:a.lon??null,altitude_ft:a.alt_baro??a.alt_geom??null,groundspeed_kt:a.gs??null,track_deg:a.track??null,seen_s:a.seen??null}}catch{return null}}
async function airframeHistoryFallback(hex,call){const live=await adsblolLive(hex);if(live)return{source:'ADSB.lol',kind:'airframe-state',state:live,history_available:false,archive_available:true,archive_source:'ADSB.lol daily globe history',history_license:'ODbL-1.0'};const dossier=await adsbdbDossier(hex,call);if(dossier)return{source:'ADSBdb',kind:'identity-route',aircraft:dossier.aircraft||null,flight:dossier.flight||null,history_available:false};return null}
async function adsbdbDossier(hex,call){const id=String(hex||'').trim().toUpperCase(),cs=String(call||'').trim().toUpperCase();if(!id)return null;try{const url='https://api.adsbdb.com/v0/aircraft/'+encodeURIComponent(id)+(cs?'?callsign='+encodeURIComponent(cs):'');const r=await fetch(url,{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0','Accept':'application/json'}});if(!r.ok)return null;const j=await r.json(),z=j?.response||{},a=z.aircraft||null,x=z.flightroute||z.flight_route||null;if(!a&&!x)return null;return{aircraft:a,flight:x?{flight_icao:x.callsign_icao||cs||x.callsign||null,flight_iata:x.callsign_iata||null,airline_name:x.airline?.name||null,airline_icao:x.airline?.icao||null,airline_iata:x.airline?.iata||null,dep_iata:x.origin?.iata_code||null,dep_icao:x.origin?.icao_code||null,dep_name:x.origin?.name||null,arr_iata:x.destination?.iata_code||null,arr_icao:x.destination?.icao_code||null,arr_name:x.destination?.name||null,resolution:'adsbdb-combined'}:null}}catch{return null}}
async function vrsRoute(call){const cs=String(call||'').trim().toUpperCase().replace(/\s+/g,'');if(!/^[A-Z]{2,3}[A-Z0-9]{1,6}$/.test(cs))return null;const prefixes=[cs.slice(0,3),cs.slice(0,2)].filter(x=>/^[A-Z]+$/.test(x));for(const p of [...new Set(prefixes)])try{const r=await fetch('https://vrs-standing-data.adsb.lol/routes/'+p+'/'+encodeURIComponent(cs)+'.json',{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0','Accept':'application/json'},cf:{cacheTtl:3600,cacheEverything:true}});if(!r.ok)continue;const j=await r.json(),x=Array.isArray(j)?j[0]:j;if(!x)continue;const dep=x.From||x.from||x.Origin||x.origin||x.FromCode||x.from_code,arr=x.To||x.to||x.Destination||x.destination||x.ToCode||x.to_code;if(!dep||!arr)continue;return{flight_icao:cs,dep_iata:String(dep).toUpperCase(),arr_iata:String(arr).toUpperCase(),airline_name:x.Operator||x.operator||null,resolution:'vrs-standing-route'}}catch{}return null}
async function resolveRouteFree(call){let r=await vrsRoute(call);if(r)return{...r,source:'VRS standing data'};r=await adsbdbRoute(call);return r?{...r,source:'ADSBdb'}:null}
async function adsbdbRoute(call){const cs=String(call||'').trim().toUpperCase();if(!cs)return null;const aliases={ROU:'ACA',JZA:'ACA',WEN:'WJA'},iata={ACA:'AC',JZA:'QK',WJA:'WS',WEN:'WR',ROU:'RV',UAL:'UA',AAL:'AA',DAL:'DL',AFR:'AF',BAW:'BA',KLM:'KL',DLH:'LH',TSC:'TS',POE:'PD'},tries=[cs];const p=cs.slice(0,3),n=cs.slice(3);if(iata[p]&&n)tries.push(iata[p]+n);if(aliases[p]&&n){tries.push(aliases[p]+n);if(iata[aliases[p]])tries.push(iata[aliases[p]]+n)}for(const q of [...new Set(tries)]){try{const r=await fetch('https://api.adsbdb.com/v0/callsign/'+encodeURIComponent(q),{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0 (+https://github.com/brenton-collab/doaa-calibration)','Accept':'application/json'}});if(!r.ok)continue;const j=await r.json(),x=j?.response?.flightroute;if(!x)continue;const o=x.origin||{},d=x.destination||{},ac=x.airline||{};return{flight_icao:cs,flight_iata:(iata[p]&&n?iata[p]+n:null),airline_name:ac.name||null,airline_icao:ac.icao||p,dep_iata:o.iata_code||o.iata||null,dep_icao:o.icao_code||o.icao||null,dep_name:o.name||null,arr_iata:d.iata_code||d.iata||null,arr_icao:d.icao_code||d.icao||null,arr_name:d.name||null,resolution:'adsbdb-route'}}catch{}}return null}
async function planespottersPhoto(hex,reg){const id=String(hex||'').trim().toUpperCase(),registration=String(reg||'').trim().toUpperCase();const urls=[];if(id)urls.push('https://api.planespotters.net/pub/photos/hex/'+encodeURIComponent(id));if(registration)urls.push('https://api.planespotters.net/pub/photos/reg/'+encodeURIComponent(registration));for(const url of urls){try{const r=await fetch(url,{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0 (+https://github.com/brenton-collab/doaa-calibration)','Accept':'application/json'}});if(!r.ok)continue;const j=await r.json(),p=j?.photos?.[0];if(!p)continue;const image=p.thumbnail_large?.src||p.thumbnail_large||p.thumbnail?.src||p.thumbnail||p.image?.src||p.image;if(!image||typeof image!=='string')continue;return{source:'Planespotters.net',title:(registration||id)+' aircraft photo',page:p.link||p.url||null,image,artist:p.photographer||null,license:null,credit:p.photographer||null}}catch{}}return null}
async function commonsPhoto(term,strict=true){if(!term)return null;const api='https://commons.wikimedia.org/w/api.php?',base={action:'query',prop:'imageinfo',iiprop:'url|extmetadata',iiurlwidth:'900',format:'json',origin:'*'},clean=x=>String(x||'').toUpperCase().replace(/[^A-Z0-9]/g,''),needle=clean(term);async function query(p){const r=await fetch(api+new URLSearchParams({...base,...p}),{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0 (personal aviation display)','Accept':'application/json'}});if(!r.ok)throw Error('commons '+r.status);const j=await r.json();return Object.values(j?.query?.pages||{})}async function category(title){const r=await fetch(api+new URLSearchParams({action:'query',list:'categorymembers',cmtitle:title,cmtype:'file',cmlimit:'20',format:'json',origin:'*'}),{headers:{'User-Agent':'DOAA-Ottawa-Aviation/1.0 (personal aviation display)','Accept':'application/json'}});if(!r.ok)throw Error('commons category '+r.status);const j=await r.json(),titles=(j?.query?.categorymembers||[]).map(x=>x.title);if(!titles.length)return[];return query({titles:titles.join('|')})}let out=[];if(strict){for(const cat of ['Category:'+term+' (aircraft)','Category:'+term]){out=await category(cat);if(out.length)break}if(!out.length)out=await query({generator:'search',gsrsearch:'intitle:'+term,gsrnamespace:'6',gsrlimit:'20'});out=out.filter(p=>clean(p.title).includes(needle))}else{for(const cat of ['Category:'+term,'Category:'+term+' aircraft']){out=await category(cat);if(out.length)break}if(!out.length)out=await query({generator:'search',gsrsearch:term+' aircraft',gsrnamespace:'6',gsrlimit:'20'})}const p=out.find(x=>x?.imageinfo?.[0]);if(!p)return null;const i=p.imageinfo[0],m=i.extmetadata||{};return{title:p.title,page:i.descriptionurl||null,image:i.thumburl||i.url||null,artist:m.Artist?.value||null,license:m.LicenseShortName?.value||null,credit:m.Credit?.value||null}}
